import torch, torch.nn as nn, math
torch.set_grad_enabled(False)
class PosEnc(nn.Module):
    def __init__(self):
        super().__init__()
        d_model, max_len = 128, 5000
        pe = torch.zeros(max_len, d_model)
        position = torch.arange(0, max_len, dtype=torch.float).unsqueeze(1)
        div = torch.exp(torch.arange(0, d_model, 2).float() * (-math.log(10000.0)/d_model))
        pe[:,0::2] = torch.sin(position*div); pe[:,1::2] = torch.cos(position*div)
        self.register_buffer('pe', pe.unsqueeze(0))
    def forward(self,x,off=0): return x + self.pe[:, off:off+x.size(1)]

def build(pe_src, pe_tgt, causal, norm_first, enc_norm):
    class M(nn.Module):
        def __init__(self):
            super().__init__()
            self.embedding = nn.Linear(64,128); self.pos_encoder = PosEnc()
            self.transformer_encoder = nn.TransformerEncoder(
                nn.TransformerEncoderLayer(128,8,256,0.1,batch_first=True,norm_first=norm_first),
                3, nn.LayerNorm(128) if enc_norm else None)
            self.transformer_decoder = nn.TransformerDecoder(
                nn.TransformerDecoderLayer(128,8,256,0.1,batch_first=True,norm_first=norm_first),1)
            self.output_layer = nn.Linear(128,64)
        def feat(self, src, tgt):
            s = self.embedding(src)
            if pe_src: s = self.pos_encoder(s)
            mem = self.transformer_encoder(s)
            t = self.embedding(tgt)
            if pe_tgt: t = self.pos_encoder(t)
            mask = torch.nn.Transformer.generate_square_subsequent_mask(t.size(1)) if causal else None
            return self.transformer_decoder(t, mem, tgt_mask=mask)
        def forward(self,src,tgt): return self.output_layer(self.feat(src,tgt))
    return M()

w = torch.load('/app/weights.pt', map_location='cpu')
d = torch.load('/app/dataset.pt', map_location='cpu')
src,tgt = d['src_sequences'], d['tgt_sequences']

def score(F, lam=0.01):
    Fb = F.reshape(20,20,128).double(); Yb = tgt.reshape(20,20,64).double()
    tr = torch.arange(16); te = torch.arange(16,20)
    Xtr,Ytr = Fb[tr].reshape(-1,128), Yb[tr].reshape(-1,64)
    Xte,Yte = Fb[te].reshape(-1,128), Yb[te].reshape(-1,64)
    mu = Xtr.mean(0); A=(Xtr-mu).T@(Xtr-mu)+lam*torch.eye(128,dtype=torch.float64)
    W=torch.linalg.solve(A,(Xtr-mu).T@(Ytr-Ytr.mean(0))); b=Ytr.mean(0)-mu@W
    l=lambda X,Y: nn.functional.mse_loss(X@W+b,Y).item()
    return l(Xtr,Ytr), l(Xte,Yte)

