def forward(
    self, src: torch.Tensor, tgt: Optional[torch.Tensor] = None
) -> torch.Tensor:
    # tgt is the teacher-forced decoder input; if it is omitted the source
    # sequence is used as the decoder input.
    if tgt is None:
        tgt = src
    return self.output_layer(self.features(src, tgt))
